"""Every container backend fixture, loaded from a descriptor generated by the
real tdx-system / tdx-domain create path (provisioning mocked in conftest).
clickhouse / starrocks stage a SYS_PATH on the *system* (domains don't export
one)."""
from __future__ import annotations

from pathlib import Path

import pytest

from tabsdatax.itest.fixture import backend as common
from tabsdatax.itest.tdksystems import tdx
from tabsdatax.itest.fixture.backends.clickhouse import ClickhouseDomain, ClickhouseSystem
from tabsdatax.itest.fixture.backends.db2 import Db2Domain, Db2System
from tabsdatax.itest.fixture.backends.mongodb import MongodbDomain, MongodbSystem
from tabsdatax.itest.fixture.backends.mssqlserver import MssqlserverDomain, MssqlserverSystem
from tabsdatax.itest.fixture.backends.mysql import (
    MysqlDomain,
    MysqlSystem,
    mysql_domain,
    mysql_system,
)
from tabsdatax.itest.fixture.backends.oracle import OracleDomain, OracleSystem
from tabsdatax.itest.fixture.backends.postgres import PostgresDomain, PostgresSystem
from tabsdatax.itest.fixture.backends.redpanda import RedpandaDomain, RedpandaSystem
from tabsdatax.itest.fixture.backends.starrocks import StarrocksDomain, StarrocksSystem

# slug, system_kind, staging, SystemCls, DomainCls
CONTAINER = [
    ("mysql", "sql", False, MysqlSystem, MysqlDomain),
    ("postgres", "sql", False, PostgresSystem, PostgresDomain),
    ("mssqlserver", "sql", False, MssqlserverSystem, MssqlserverDomain),
    ("oracle", "sql", False, OracleSystem, OracleDomain),
    ("db2", "sql", False, Db2System, Db2Domain),
    ("mongodb", "mongodb", False, MongodbSystem, MongodbDomain),
    ("redpanda", "kafka", False, RedpandaSystem, RedpandaDomain),
    ("clickhouse", "sql", True, ClickhouseSystem, ClickhouseDomain),
    ("starrocks", "sql", True, StarrocksSystem, StarrocksDomain),
]
IDS = [c[0] for c in CONTAINER]


@pytest.mark.parametrize("slug,kind,staging,Sys,Dom", CONTAINER, ids=IDS)
def test_container_system(provision, slug, kind, staging, Sys, Dom):
    provision.system(slug, "s")
    obj = common.load("s", Sys)
    assert isinstance(obj, Sys) and obj.system_type == slug
    assert obj.system_kind == kind and obj.host == "localhost"
    assert obj.container == "tdx_s" and obj.image  # tdx_-prefixed name + image
    if staging:
        assert isinstance(obj.sys_path, Path)


@pytest.mark.parametrize("slug,kind,staging,Sys,Dom", CONTAINER, ids=IDS)
def test_container_domain(provision, slug, kind, staging, Sys, Dom):
    provision.system(slug, "s")
    provision.domain(slug, "s", "d")
    obj = common.load("d", Dom)
    assert isinstance(obj, Dom) and obj.system_type == slug
    assert obj.system_kind == kind and obj.host == "localhost"
    # The entity (db) is the prefixed external name (default DOMAIN_PREFIX);
    # the descriptor's logical name stays "d".
    ext = tdx._resolve_domain_prefix(None) + "d"
    assert obj.db == ext and obj.sqlalchemy_uri == f"proto://{ext}"
    assert obj.model is None and obj.data is None


@pytest.fixture
def mysql_ready(provision):
    provision.system("mysql", "db")
    provision.domain("mysql", "db", "shop")


@mysql_system("db")
@mysql_domain("shop")
def test_container_injection(
    mysql_ready, system_db: MysqlSystem, domain_shop: MysqlDomain
):
    assert isinstance(system_db, MysqlSystem)
    assert isinstance(domain_shop, MysqlDomain)
    assert system_db.name == "db" and domain_shop.name == "shop"
